import { DEFAULT_HERITAGE_THEME_TUNING, HERITAGE_AMBIENT_PATTERNS, HERITAGE_AMBIENT_SCOPES, HERITAGE_AMBIENT_LAYER_SELECTIONS, HERITAGE_DENSITY_MODES, HERITAGE_PERFORMANCE_MODES, HERITAGE_LIGHT_REVERSIBLE_TUNING_KEYS, HERITAGE_PALETTES, clampHeritageThemeTuning, type HeritageAmbientMotion as AmbientMotion, type HeritageAmbientPattern as AmbientPattern, type HeritageAmbientScope as AmbientScope, type HeritageAmbientLayerSelection as AmbientLayerSelection, type HeritageDensityMode as DensityMode, type HeritagePerformanceMode as PerformanceMode, type HeritageMode as Mode, type HeritagePalette as Palette, type HeritageSceneIntensity as SceneIntensity, type HeritageTabHierarchyMode as TabHierarchyMode, type HeritageThemeTuning as ThemeTuning } from "./theme/schema";
import { HERITAGE_BACKGROUND_OPTIONS, HERITAGE_BRAND_ART_OPTIONS, HERITAGE_SPLASH_ART_OPTIONS, applyHeritageVisualAssetsBuiltInPreset, exportHeritageVisualAssetsPreset, getHeritageBackgroundLabel, getHeritageBackgroundOption, getResolvedHeritageBackgroundEngine, importHeritageVisualAssetsPreset, isHeritageVisualAssetFavorite, optimizeHeritageVisualAsset, resetHeritageVisualAssets, resolveHeritageBackgroundSource, setHeritageVisualAssets, toggleHeritageVisualAssetFavorite, useHeritageVisualAssetsSnapshot, type HeritageBackgroundArt, type HeritageBackgroundEngine, type HeritageBrandArt, type HeritageSplashArt } from "../heritageVisualAssets";
import { DEFAULT_HERITAGE_LAYOUT, HERITAGE_LAYOUT_LIMITS, isDefaultHeritageLayout, resetHeritageLayout, updateHeritageLayout, useHeritageLayoutSnapshot, type HeritageLayoutSnapshot } from "../heritageLayout";

const PALETTES:Palette[]=[...HERITAGE_PALETTES];
const DEFAULT_THEME_TUNING=DEFAULT_HERITAGE_THEME_TUNING;
const clampThemeTuning=clampHeritageThemeTuning;

function SunIcon({size=17}:{size?:number}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="3.8" stroke="currentColor" strokeWidth="1.7"/><path d="M12 2.8v2.1M12 19.1v2.1M2.8 12h2.1M19.1 12h2.1M5.5 5.5L7 7M17 17l1.5 1.5M18.5 5.5L17 7M7 17l-1.5 1.5" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round"/></svg>}
function MoonIcon({size=17}:{size?:number}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M19.3 15.3A8 8 0 118.7 4.7a6.4 6.4 0 0010.6 10.6z" stroke="currentColor" strokeWidth="1.7" strokeLinejoin="round"/></svg>}
function SceneIcon({size=17}:{size?:number}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3.5 17.5l5-5 3.2 3.1 3.7-4.3 5.1 6.2" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"/><circle cx="16.8" cy="7.2" r="2" stroke="currentColor" strokeWidth="1.5"/><rect x="3" y="4" width="18" height="16" rx="2.8" stroke="currentColor" strokeWidth="1.7"/></svg>}
function GlassIcon({size=17}:{size?:number}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="4" stroke="currentColor" strokeWidth="1.7"/><path d="M7 9c2.2 1.3 7.8 1.3 10 0M7 15c2.2 1.3 7.8 1.3 10 0" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" opacity=".85"/></svg>}
function ThemeSettingsIcon({size=17}:{size?:number}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 6h14M8 12h11M5 18h14" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round"/><circle cx="8" cy="6" r="2" fill="var(--bg-elev)" stroke="currentColor" strokeWidth="1.6"/><circle cx="15" cy="12" r="2" fill="var(--bg-elev)" stroke="currentColor" strokeWidth="1.6"/><circle cx="10" cy="18" r="2" fill="var(--bg-elev)" stroke="currentColor" strokeWidth="1.6"/></svg>}
function FavoriteIcon({size=15,filled=false}:{size?:number;filled?:boolean}) {return <svg className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill={filled?"currentColor":"none"} aria-hidden="true"><path d="M12 3.8l2.45 4.96 5.48.8-3.97 3.87.94 5.47L12 16.42 7.1 18.9l.94-5.47-3.97-3.87 5.48-.8L12 3.8z" stroke="currentColor" strokeWidth="1.45" strokeLinejoin="round"/></svg>}

export function AppearanceStudio() {
  const {t,locale}=useI18n();
  const appearance=useHeritageAppearanceSnapshot();
  const visualAssets=useHeritageVisualAssetsSnapshot();
  const {palette,mode,scene,ambientMotion,ambientPattern,ambientScope,ambientLayers,ambientDither,glassMode,tabHierarchy,density,performanceMode,tuning:themeTuning}=appearance;
  const setPalette=(value:Palette)=>setHeritageAppearance({palette:value});
  const setMode=(value:Mode)=>setHeritageAppearance({mode:value});
  const setScene=(value:SceneIntensity)=>setHeritageAppearance({scene:value});
  const setAmbientMotion=(value:AmbientMotion)=>setHeritageAppearance({ambientMotion:value});
  const setAmbientPattern=(value:AmbientPattern)=>setHeritageAppearance({ambientPattern:value});
  const setAmbientScope=(value:AmbientScope)=>setHeritageAppearance({ambientScope:value});
  const setAmbientLayers=(value:AmbientLayerSelection)=>setHeritageAppearance({ambientLayers:value});
  const setAmbientDither=(value:boolean)=>setHeritageAppearance({ambientDither:value});
  const setGlassMode=(value:boolean)=>setHeritageAppearance({glassMode:value});
  const setTabHierarchy=(value:TabHierarchyMode)=>setHeritageAppearance({tabHierarchy:value});
  const setDensity=(value:DensityMode)=>setHeritageAppearance({density:value});
  const setPerformanceMode=(value:PerformanceMode)=>setHeritageAppearance({performanceMode:value});
  const setThemeTuning=(value:ThemeTuning)=>setHeritageThemeTuning(value);
  const triggerRef=useRef<HTMLButtonElement>(null);
  const panelRef=useRef<HTMLElement>(null);
  const [settingsOpen,setSettingsOpen]=useState(false);
  const [activeStudioSection,setActiveStudioSection]=useState<string|null>(null);
  const [themeCopied,setThemeCopied]=useState(false);
  const [themePresetStatus,setThemePresetStatus]=useState<"idle"|"imported"|"invalid">("idle");
  const [autoPaletteRefreshing,setAutoPaletteRefreshing]=useState(false);
  const themeFileRef=useRef<HTMLInputElement>(null);
  const backgroundFileRef=useRef<HTMLInputElement>(null);const brandFileRef=useRef<HTMLInputElement>(null);const splashFileRef=useRef<HTMLInputElement>(null);
  const [assetStatus,setAssetStatus]=useState<"idle"|"working"|"saved"|"error">("idle");
  const L=(en:string,fa:string)=>uiText(locale, en, fa);
  const closeSettings=(returnFocus=false)=>{setSettingsOpen(false);setActiveStudioSection(null);if(returnFocus)requestAnimationFrame(()=>triggerRef.current?.focus());};
  const toggleSettings=()=>{if(settingsOpen)closeSettings();else setSettingsOpen(true);};
  useEffect(()=>{
    if(!settingsOpen)return;
    const frame=requestAnimationFrame(()=>panelRef.current?.focus({preventScroll:true}));
    const close=(event:PointerEvent)=>{const target=event.target as Node;if(!panelRef.current?.contains(target)&&!triggerRef.current?.contains(target))closeSettings()};
    const escape=(event:KeyboardEvent)=>{if(event.key==="Escape"){event.preventDefault();closeSettings(true)}};
    addEventListener("pointerdown",close);addEventListener("keydown",escape);return()=>{cancelAnimationFrame(frame);removeEventListener("pointerdown",close);removeEventListener("keydown",escape)};
  },[settingsOpen]);
  useEffect(() => {
    const open = () => { setSettingsOpen(true); setActiveStudioSection("appearance-navigation"); };
    window.addEventListener("heritage:open-appearance", open);
    return () => window.removeEventListener("heritage:open-appearance", open);
  }, []);
  const palettes:Palette[]=PALETTES;
  const paletteLabel=(value:Palette)=>value==="auto"?L("Auto · Scene","خودکار · صحنه"):value==="neutral"?L("Neutral","خنثی"):value==="heritage"?L("Heritage","میراث"):value==="midnight"?L("Midnight","نیمه‌شب"):L("Oxblood","زرشکی");
  const scenes:SceneIntensity[]=["subtle","rich","full"];
  const sceneLabel=(value:SceneIntensity)=>value==="subtle"?t("theme.sceneSubtle"):value==="rich"?t("theme.sceneRich"):t("theme.sceneFull");
  const ambientPatternLabel=(value:AmbientPattern)=>value==="organic"?L("Organic drift","حرکت ارگانیک"):value==="chromatic"?L("Chromatic depth","عمق رنگی"):value==="orbit"?L("Orbiting light","گردش نور"):value==="drift"?L("Flowing drift","حرکت روان"):L("Breathe","تنفس");
  const lightToneReversed=mode==="light"&&themeTuning.reverseLightBrightness>=.5;
  const lightReversible=(key:keyof ThemeTuning)=>HERITAGE_LIGHT_REVERSIBLE_TUNING_KEYS.includes(key as (typeof HERITAGE_LIGHT_REVERSIBLE_TUNING_KEYS)[number]);
  const tune=(key:keyof ThemeTuning,value:number)=>setThemeTuning(clampThemeTuning({...themeTuning,[key]:value}));
  const recalculateAutoPalette=async()=>{setAutoPaletteRefreshing(true);try{await refreshHeritageAutoPalette();}finally{setAutoPaletteRefreshing(false);}};
  const themePayload=()=>({...exportHeritageThemePreset(),visualAssets:exportHeritageVisualAssetsPreset()});
  const copyThemeJson=async()=>{
    try{await navigator.clipboard.writeText(JSON.stringify(themePayload(),null,2));setThemeCopied(true);setTimeout(()=>setThemeCopied(false),1600);}catch{setThemeCopied(false);}
  };
  const downloadThemeJson=()=>{
    const blob=new Blob([JSON.stringify(themePayload(),null,2)],{type:"application/json"});
    const href=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=href;anchor.download=`horse-registry-theme-${palette}-${mode}.json`;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(href),0);
  };
  const importThemeJson=async(event:React.ChangeEvent<HTMLInputElement>)=>{
    const file=event.currentTarget.files?.[0];event.currentTarget.value="";if(!file)return;
    try{const parsed=JSON.parse(await file.text());const themeImported=importHeritageThemePreset(parsed);const assetsImported=importHeritageVisualAssetsPreset(parsed);if(!themeImported&&!assetsImported)throw new Error("Invalid theme preset");setThemePresetStatus("imported");setTimeout(()=>setThemePresetStatus("idle"),2200);}catch{setThemePresetStatus("invalid");setTimeout(()=>setThemePresetStatus("idle"),2600);}
  };
  const refreshPaletteAfterSceneChange=()=>{if(palette==="auto")requestAnimationFrame(()=>void refreshHeritageAutoPalette());};
  const applyBuiltInPreset=(preset:HeritageBuiltInPreset)=>{applyHeritageBuiltInPreset(preset);applyHeritageVisualAssetsBuiltInPreset(preset);requestAnimationFrame(()=>void refreshHeritageAutoPalette());};
  const backgroundLabel=(value:HeritageBackgroundArt)=>getHeritageBackgroundLabel(value,locale==="fa"?"fa":"en");
  const brandLabel=(value:HeritageBrandArt)=>HERITAGE_BRAND_ART_OPTIONS.find(option=>option.id===value)?.label??value;
  const splashLabel=(value:HeritageSplashArt)=>{const option=HERITAGE_SPLASH_ART_OPTIONS.find(item=>item.id===value);return option?(locale==="fa"?(option.labelFa??option.label):option.label):value;};
  const favoriteTitle=(active:boolean)=>active?L("Remove from favorites","حذف از علاقه‌مندی‌ها"):L("Add to favorites","افزودن به علاقه‌مندی‌ها");
  const backgroundGalleryOptions=useMemo(()=>HERITAGE_BACKGROUND_OPTIONS.map(option=>option).filter(option=>option.mode==="both"||option.mode===mode),[mode]);
  const selectedBackgroundOption=useMemo(()=>getHeritageBackgroundOption(visualAssets.backgroundArt,mode),[mode,visualAssets.backgroundArt]);
  const currentBackgroundScene3D=selectedBackgroundOption?.threeD;
  const currentBackgroundEngine=getResolvedHeritageBackgroundEngine(visualAssets,mode);
  const backgroundEngineLabel=(value:HeritageBackgroundEngine)=>({flat:L("Flat artwork","تصویر تخت"),layers:L("3D layers","لایه‌های سه‌بعدی")}[value]);
  const backgroundEngineSub=(value:HeritageBackgroundEngine)=>({flat:L("Classic lightweight wallpaper","پس‌زمینه سبک کلاسیک"),layers:L("Multi-layer parallax scene","صحنه چندلایه پارالاکس")}[value]);
  const selectBackground=(value:HeritageBackgroundArt)=>{
    if(value==="custom"&&!visualAssets.customBackground){backgroundFileRef.current?.click();return;}
    const option=getHeritageBackgroundOption(value,mode);
    const patch:{backgroundArt:HeritageBackgroundArt;backgroundEngine?:HeritageBackgroundEngine}={backgroundArt:value};
    if(option?.threeD)patch.backgroundEngine=option.threeD.preferredEngine??"layers";
    else patch.backgroundEngine="flat";
    setHeritageVisualAssets(patch);
    refreshPaletteAfterSceneChange();
  };
  const uploadAsset=async(kind:"background"|"brand"|"splash",event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.currentTarget.files?.[0];event.currentTarget.value="";if(!file)return;setAssetStatus("working");try{const data=await optimizeHeritageVisualAsset(file,kind);const saved=kind==="background"?setHeritageVisualAssets({customBackground:data,backgroundArt:"custom"}):kind==="brand"?setHeritageVisualAssets({customBrand:data,brandArt:"custom"}):setHeritageVisualAssets({customSplash:data,splashArt:"custom"});if(!saved)throw new Error("Storage quota exceeded");if(kind==="background")refreshPaletteAfterSceneChange();setAssetStatus("saved");setTimeout(()=>setAssetStatus("idle"),1800);}catch{setAssetStatus("error");setTimeout(()=>setAssetStatus("idle"),2600);}};
  const assetRange=(label:string,value:number,min:number,max:number,onChange:(value:number)=>void)=><label className="theme-asset-range"><span><strong>{label}</strong><b>{tuningFormatter.format(value)}%</b></span><input type="range" min={min} max={max} step="1" value={value} onChange={event=>onChange(Number(event.currentTarget.value))}/></label>;
  const layoutTuning=useHeritageLayoutSnapshot();
  const layoutTuned=!isDefaultHeritageLayout(layoutTuning);
  const layoutSlider=(key:keyof HeritageLayoutSnapshot,label:string,tip:string)=>{
    const value=layoutTuning[key];
    const [min,max,step]=HERITAGE_LAYOUT_LIMITS[key];
    const progress=Math.max(0,Math.min(100,((value-min)/(max-min))*100));
    return <label className="theme-tuning-slider" style={{"--theme-range-progress":`${progress}%`} as React.CSSProperties}>
      <span className="theme-slider-meta"><span className="theme-slider-name">{label}{help(tip)}</span><b dir="auto">{tuningFormatter.format(value)}{key==="contentWidth"?L("px","پیکسل"):"px"}</b></span>
      <input dir="ltr" aria-label={label} title={tip} type="range" min={min} max={max} step={step} value={value} onChange={e=>updateHeritageLayout(key,Number(e.target.value))}/>
    </label>;
  };
  const help=(text:string)=><span className="theme-help" tabIndex={0} role="img" aria-label={text} data-tip={text}>?</span>;
  const tuningFormatter=useMemo(()=>new Intl.NumberFormat(uiNumberTag(locale),{maximumFractionDigits:2,useGrouping:false}),[locale]);
  const formatTuningValue=(value:number,suffix:string,signed=false)=>{const number=tuningFormatter.format(value);const unit=locale==="fa"?(suffix==="%"?"٪":suffix==="px"?" پیکسل":suffix==="s"?" ثانیه":suffix):suffix;return `${signed&&value>0?"+":""}${number}${unit}`;};
  const slider=(key:keyof ThemeTuning,label:string,min:number,max:number,step:number,suffix:string,tip:string,bipolarLabels?:readonly [string,string,string])=>{
    const value=themeTuning[key];
    const bipolar=min<0&&max>0;
    const progress=Math.max(0,Math.min(100,((value-min)/(max-min))*100));
    const scale=bipolarLabels??[L("Darker","تیره‌تر"),L("Neutral","خنثی"),L("Brighter","روشن‌تر")];
    const displayScale=lightToneReversed&&lightReversible(key)?[scale[2],scale[1],scale[0]] as const:scale;
    const effectiveTip=lightToneReversed&&lightReversible(key)?`${tip} ${L("Light-mode polarity is mirrored, so this signed control currently works in the opposite direction from Dark mode.","قطبیت حالت روشن معکوس است؛ بنابراین این کنترل علامت‌دار اکنون در جهت مخالف حالت تیره عمل می‌کند.")}`:tip;
    return <label className={`theme-tuning-slider${bipolar?" is-bipolar":""}${lightToneReversed&&lightReversible(key)?" is-light-reversed":""}`} style={{"--theme-range-progress":`${progress}%`} as React.CSSProperties}>
      <span className="theme-slider-meta"><span className="theme-slider-name">{label}{help(effectiveTip)}</span><b dir="auto">{formatTuningValue(value,suffix,bipolar)}</b></span>
      <input dir="ltr" aria-label={label} title={effectiveTip} type="range" min={min} max={max} step={step} value={value} onChange={e=>tune(key,Number(e.target.value))}/>
      {bipolar&&<span className="theme-slider-scale" aria-hidden="true"><span>{displayScale[0]}</span><span>{displayScale[1]}</span><span>{displayScale[2]}</span></span>}
    </label>;
  };
  const [registryVisualEncoding,setRegistryVisualEncoding]=useState(readVisualEncoding);
  const checkbox=(key:keyof ThemeTuning,label:string,tip:string)=><label className="theme-checkbox-row" title={tip}><input type="checkbox" checked={themeTuning[key]>=.5} onChange={e=>tune(key,e.target.checked?1:0)}/><span className="theme-checkbox-copy"><strong>{label}{help(tip)}</strong><small>{tip}</small></span></label>;
  const row=(label:string,tip:string,control:React.ReactNode)=><div className="theme-setting-row"><div className="theme-setting-copy"><strong>{label}{help(tip)}</strong></div>{control}</div>;
  const scrollToStudioSection=(id:string)=>panelRef.current?.querySelector<HTMLElement>(`#${id}`)?.scrollIntoView({behavior:"smooth",block:"nearest"});
  const toggleStudioSection=(id:string)=>setActiveStudioSection(current=>current===id?null:id);
  const openStudioSection=(id:string)=>{setActiveStudioSection(id);requestAnimationFrame(()=>scrollToStudioSection(id));};
  const studioSections=[
    {id:"appearance-foundation",short:L("Base","پایه"),label:L("Foundation","پایه بصری"),tone:"foundation"},
    {id:"appearance-artwork",short:L("Art","هنر"),label:L("Background & artwork","پس‌زمینه و نشان"),tone:"artwork"},
    {id:"appearance-material",short:L("Material","متریال"),label:L("Material & frost","متریال و ماتی"),tone:"material"},
    {id:"appearance-lighting",short:L("Light","نور"),label:L("Ambient & shine","نور و درخشش"),tone:"lighting"},
    {id:"appearance-color",short:L("Color","رنگ"),label:L("Color & meaning","رنگ و معنا"),tone:"color"},
    {id:"appearance-navigation",short:L("Nav","ناوبری"),label:L("Navigation","ناوبری"),tone:"navigation"},
    {id:"appearance-presets",short:L("Preset","ذخیره"),label:L("Presets & reset","پیش‌تنظیم و بازنشانی"),tone:"preset"},
  ] as const;
  const settingsPanel=<aside id="heritage-appearance-studio" role="dialog" tabIndex={-1} ref={panelRef} className="theme-settings-popover theme-settings-sidebar theme-studio-v20" data-h-surface-role="major" dir={(isUiRtl(locale) ? "rtl" : "ltr")} aria-label={L("Appearance studio","استودیوی ظاهر")}>
    <header className="theme-studio-header">
      <div className="theme-studio-title">
        <span className="theme-studio-eyebrow">{L("YOUR PREFERENCES","تنظیمات شما")}</span>
        <strong>{L("Appearance Studio","استودیوی ظاهر")}</strong>
        <small>{L("Adjust colors, backgrounds, text and navigation. Your display preferences are saved on this device.","رنگ‌ها، پس‌زمینه، متن و پیمایش را تنظیم کنید. تنظیمات نمایش در همین دستگاه ذخیره می‌شوند.")}</small>
      </div>
      <button type="button" className="theme-studio-close" onClick={()=>closeSettings(true)} aria-label={L("Close appearance settings","بستن تنظیمات ظاهر")}>×</button>
    </header>

    <nav className="theme-studio-nav" aria-label={L("Appearance Studio sections","بخش‌های استودیوی ظاهر")}>
      {studioSections.map((section,index)=><button type="button" key={section.id} className={activeStudioSection===section.id?"active":""} data-tone={section.tone} title={section.label} aria-current={activeStudioSection===section.id?"true":undefined} onClick={()=>activeStudioSection===section.id?toggleStudioSection(section.id):openStudioSection(section.id)}><span>{String(index+1).padStart(2,"0")}</span><b>{section.short}</b></button>)}
    </nav>

    <section id="appearance-foundation" data-studio-section="foundation" data-expanded={activeStudioSection==="appearance-foundation"?"true":"false"} className="theme-settings-block theme-studio-section" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-foundation"} onClick={()=>activeStudioSection==="appearance-foundation"?toggleStudioSection("appearance-foundation"):openStudioSection("appearance-foundation")}> <span className="theme-section-index">01</span><div><strong>{L("Foundation","پایه بصری")}</strong><small>{L("Set the global canvas first. These choices establish the visual environment used by every deeper layer.","ابتدا محیط کلی را تعیین کنید؛ این گزینه‌ها پایه بصری همه لایه‌های عمیق‌تر را می‌سازند.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      {row(L("Interface mode","حالت رابط"),L("Switches the complete Core visual system between its calibrated light and dark foundations.","کل سیستم بصری هسته را بین پایه‌های تنظیم‌شده روشن و تیره جابه‌جا می‌کند."),<div className="theme-settings-choice two"><button aria-pressed={mode==="light"} className={mode==="light"?"active":""} onClick={()=>setMode("light")}><SunIcon/>{L("Light","روشن")}</button><button aria-pressed={mode==="dark"} className={mode==="dark"?"active":""} onClick={()=>setMode("dark")}><MoonIcon/>{L("Dark","تیره")}</button></div>)}
      {checkbox("reverseLightBrightness",L("Mirror Dark ↔ Light tone controls","معکوس‌سازی کنترل‌های تیره ↔ روشن"),L("When Light mode is active, every signed tone control is mirrored: Material shade, decorative scheme, semantic fills/text, contextual color, Ambient brightness and Shine brightness. A value that darkens in Dark mode brightens by the same amount in Light mode. Saturation, transparency, blur and contrast are unchanged.","در حالت روشن، همه کنترل‌های علامت‌دار روشنایی/تیرگی معکوس می‌شوند: سایه متریال، طرح تزئینی، رنگ‌های معنایی، رنگ‌های زمینه‌ای، روشنایی نور محیطی و درخشش. مقداری که در حالت تیره باعث تیرگی می‌شود، در حالت روشن به همان اندازه روشن می‌کند. اشباع، شفافیت، ماتی و کنتراست تغییر نمی‌کنند."))}
      {row(L("Color scheme","طرح رنگ"),L("Selects the decorative foundation palette. Semantic sire/dam/status colors remain independently meaningful.","پالت تزئینی پایه را انتخاب می‌کند؛ رنگ‌های معنایی پدر، مادر و وضعیت مستقل باقی می‌مانند."),<div className="theme-settings-choice palette professional">{palettes.map(value=><button key={value} data-palette-option={value} aria-pressed={palette===value} className={palette===value?"active":""} onClick={()=>setPalette(value)}><span className={`appearance-swatch ${value}`}/><b>{paletteLabel(value)}</b></button>)}</div>)}
      {palette==="auto"&&<div className="theme-auto-palette-card"><span className="theme-auto-palette-mark" aria-hidden="true">✦</span><div><strong>{L("Scene-aware color theory","هارمونی خودکار بر پایه صحنه")}</strong><small>{L("Samples the selected background artwork, finds its dominant and supporting hues, then derives a restrained foundation, accent family, warm metal harmony and split-complementary Ambient triad. Adaptive backgrounds are recalculated independently for Dark and Light modes. Sire, dam, warning, success and other semantic colors are never recolored.","تصویر پس‌زمینه انتخاب‌شده را نمونه‌برداری می‌کند، رنگ‌های غالب و پشتیبان را می‌یابد و سپس پایه‌ای کنترل‌شده، خانواده لهجه، هارمونی فلزی گرم و سه‌گانه مکمل شکافته برای نور محیطی می‌سازد. پس‌زمینه تطبیقی برای حالت‌های تیره و روشن مستقل محاسبه می‌شود. رنگ‌های معنایی پدر، مادر، هشدار، موفقیت و وضعیت هرگز بازتعریف نمی‌شوند.")}</small></div><button type="button" onClick={recalculateAutoPalette} disabled={autoPaletteRefreshing}>{autoPaletteRefreshing?L("Analyzing…","در حال تحلیل…"):L("Recalculate","محاسبه مجدد")}</button></div>}
      {row(L("Background scene","صحنه پس‌زمینه"),L("Controls how strongly the horse artwork participates behind the glass hierarchy.","شدت حضور تصویر اسب‌ها را پشت سلسله‌مراتب شیشه کنترل می‌کند."),<div className="theme-settings-choice three">{scenes.map(value=><button key={value} aria-pressed={scene===value} className={scene===value?"active":""} onClick={()=>setScene(value)}><SceneIcon size={14}/>{sceneLabel(value)}</button>)}</div>)}
      {row(L("Registry color marks","نشانه‌های رنگی ثبت"),L("Color marks for sex and status on registry table rows. On (recommended): each row carries a small visual cue so large lists scan faster. Off: plainer table.","نشانه‌گذاری رنگی جنس و وضعیت در ردیف‌های جدول ثبت. روشن (پیشنهادی): هر ردیف یک نشانهٔ بصری کوچک دارد تا مرور فهرست‌های بزرگ سریع‌تر شود. خاموش: جدول ساده‌تر."),<div className="theme-settings-choice two"><button aria-pressed={registryVisualEncoding} className={registryVisualEncoding?"active":""} onClick={()=>{setRegistryVisualEncoding(true);writeVisualEncoding(true)}}>{L("On","روشن")}</button><button aria-pressed={!registryVisualEncoding} className={!registryVisualEncoding?"active":""} onClick={()=>{setRegistryVisualEncoding(false);writeVisualEncoding(false)}}>{L("Off","خاموش")}</button></div>)}
    </section>

    <section id="appearance-artwork" data-studio-section="artwork" data-expanded={activeStudioSection==="appearance-artwork"?"true":"false"} className="theme-settings-block theme-studio-section theme-artwork-section" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-artwork"} onClick={()=>activeStudioSection==="appearance-artwork"?toggleStudioSection("appearance-artwork"):openStudioSection("appearance-artwork")}> <span className="theme-section-index">02</span><div><strong>{L("Background & artwork","پس‌زمینه و نشان")}</strong><small>{L("Choose the scene, header logo and welcome splash artwork. Built-ins remain lightweight; custom uploads are optimized locally in your browser.","صحنه، لوگوی سربرگ و تصویر اسپلش خوش‌آمدگویی را انتخاب کنید. گزینه‌های داخلی سبک می‌مانند و تصاویر سفارشی در مرورگر بهینه می‌شوند.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      <details className="theme-artwork-group theme-artwork-subsection"><summary className="theme-subgroup-head theme-subgroup-toggle"><span className="theme-subgroup-glyph">▧</span><div><strong>{L("Background artwork","تصویر پس‌زمینه")}</strong><small>{L("Auto · Scene samples this exact image when calculating the palette.","حالت خودکار · صحنه دقیقاً همین تصویر را برای محاسبه پالت نمونه‌برداری می‌کند.")}</small></div><span className="theme-subgroup-chevron" aria-hidden="true">⌄</span></summary><div className="theme-subgroup-body">
        <div className="theme-asset-gallery background-gallery">{backgroundGalleryOptions.map(option=>{const preview=option.id==="custom"?visualAssets.customBackground:resolveHeritageBackgroundSource({...visualAssets,backgroundArt:option.id},mode);const available=option.id!=="custom"||Boolean(visualAssets.customBackground);const favorite=isHeritageVisualAssetFavorite("background",option.id,visualAssets);return <div key={option.id} className={`theme-asset-card ${visualAssets.backgroundArt===option.id?"active":""}`} data-available={available?"true":"false"} data-favorite={favorite?"true":"false"}><button type="button" className={`theme-asset-option ${visualAssets.backgroundArt===option.id?"active":""}`} data-available={available?"true":"false"} aria-pressed={visualAssets.backgroundArt===option.id} onClick={()=>selectBackground(option.id)} style={preview?{"--asset-preview":`url("${preview}")`} as React.CSSProperties:undefined}><span className="theme-background-preview"/><b>{backgroundLabel(option.id)}{option.threeD&&<span className="theme-background-3d-badge">3D</span>}</b><small>{option.id==="custom"&&!available?L("Upload…","بارگذاری…"):visualAssets.backgroundArt===option.id?L("Selected","انتخاب‌شده"):option.threeD?L("3D-ready wallpaper","پس‌زمینه سه‌بعدی آماده"):option.mode==="dark"?L("Dark collection","مجموعه تیره"):option.mode==="light"?L("Light collection","مجموعه روشن"):""}</small></button><button type="button" className={`theme-asset-favorite ${favorite?"active":""}`} aria-pressed={favorite} title={favoriteTitle(favorite)} aria-label={`${favoriteTitle(favorite)} · ${backgroundLabel(option.id)}`} onClick={()=>toggleHeritageVisualAssetFavorite("background",option.id)}><FavoriteIcon filled={favorite}/></button></div>})}</div>
        <div className="theme-asset-controls two">{assetRange(L("Horizontal focus","تمرکز افقی"),visualAssets.backgroundFocusX,0,100,value=>setHeritageVisualAssets({backgroundFocusX:value}))}{assetRange(L("Vertical focus","تمرکز عمودی"),visualAssets.backgroundFocusY,0,100,value=>setHeritageVisualAssets({backgroundFocusY:value}))}</div>
        <label className="theme-background-fade-toggle theme-checkbox-row" title={L("Locks the artwork to the viewport width instead of using cover crop. The image may become vertically stretched so no side content is lost.","تصویر را به عرض کامل نما قفل می‌کند و به‌جای برش Cover از کشش استفاده می‌کند. ممکن است تصویر عمودی‌تر کشیده شود تا هیچ محتوایی از کناره‌ها حذف نشود.")}><input type="checkbox" checked={visualAssets.backgroundFitWidth} onChange={event=>setHeritageVisualAssets({backgroundFitWidth:event.target.checked})}/><span className="theme-checkbox-copy"><strong>{L("Fit full wallpaper width · stretch","برازش کامل عرض · کشیده")}</strong><small>{visualAssets.backgroundFitWidth?L("On · no horizontal crop; vertical aspect may stretch for full-width fit","فعال · بدون برش افقی؛ نسبت عمودی برای برازش کامل عرض ممکن است کشیده شود"):L("Off · normal cover crop preserves the source aspect ratio","خاموش · Cover معمولی نسبت تصویر اصلی را حفظ می‌کند")}</small></span></label>
        <label className="theme-background-fade-toggle theme-checkbox-row" title={L("Scroll parallax & zoom overscan. OFF (recommended, default): the wallpaper fits perfectly with zero zoom and never moves while you scroll. ON: a small vertical overscan is retained so the background can drift gently as the page scrolls.","پارالاکس اسکرول و بزرگ‌نمایی اضافه. خاموش (پیش‌فرض و پیشنهادی): پس‌زمینه کاملاً برازش می‌شود، بدون هیچ بزرگ‌نمایی و بدون حرکت هنگام اسکرول. فعال: کمی فضای اضافه عمودی حفظ می‌شود تا پس‌زمینه هنگام اسکرول آرام جابه‌جا شود.")}><input type="checkbox" checked={visualAssets.backgroundParallax} onChange={event=>setHeritageVisualAssets({backgroundParallax:event.target.checked})}/><span className="theme-checkbox-copy"><strong>{L("Scroll parallax & overscan","پارالاکس اسکرول و بزرگ‌نمایی")}</strong><small>{visualAssets.backgroundParallax?L("On · wallpaper breathes with scrolling (slight zoom retained)","فعال · پس‌زمینه با اسکرول نفس می‌کشد (کمی بزرگ‌نمایی حفظ می‌شود)"):L("Off · perfectly fitted, zero zoom, no scroll movement (default)","خاموش · برازش کامل، بدون بزرگ‌نمایی و بدون حرکت اسکرول (پیش‌فرض)")}</small></span></label>
        {currentBackgroundScene3D&&<><div className="theme-background-engine-grid">{(["flat","layers"] as HeritageBackgroundEngine[]).map(engine=>{const supported=engine==="flat"||currentBackgroundScene3D.layerSources.length>0;const active=currentBackgroundEngine===engine;return <button key={engine} type="button" className={`theme-background-engine-chip ${active?"active":""}`} aria-pressed={active} disabled={!supported} onClick={()=>supported&&setHeritageVisualAssets({backgroundEngine:engine})}><span><strong>{backgroundEngineLabel(engine)}</strong><small>{supported?backgroundEngineSub(engine):L("Not available for this wallpaper","برای این پس‌زمینه موجود نیست")}</small></span></button>})}</div><div className="theme-asset-controls two">{assetRange(L("3D strength","شدت سه‌بعدی"),visualAssets.background3DStrength,20,180,value=>setHeritageVisualAssets({background3DStrength:value}))}{assetRange(L("3D zoom","بزرگ‌نمایی سه‌بعدی"),visualAssets.background3DZoom,75,125,value=>setHeritageVisualAssets({background3DZoom:value}))}</div><label className="theme-background-fade-toggle theme-checkbox-row" title={L("Adds a small autonomous drift so the wallpaper feels alive even before scrolling or moving the mouse.","یک حرکت خودکار ظریف اضافه می‌کند تا پس‌زمینه حتی قبل از حرکت ماوس یا اسکرول زنده‌تر حس شود.")}><input type="checkbox" checked={visualAssets.background3DAutoMotion} onChange={event=>setHeritageVisualAssets({background3DAutoMotion:event.target.checked})}/><span className="theme-checkbox-copy"><strong>{L("Autonomous drift","حرکت خودکار")}</strong><small>{visualAssets.background3DAutoMotion?L("On · subtle living motion is active","فعال · حرکت ظریف زنده فعال است"):L("Off · motion responds only to pointer and scroll","خاموش · حرکت فقط به ماوس و اسکرول پاسخ می‌دهد")}</small></span></label><label className="theme-background-fade-toggle theme-checkbox-row" title={L("Adds a touch of atmospheric softness to the far layers. Most noticeable in the multi-layer renderer.","به لایه‌های دورتر کمی نرمی فضایی می‌دهد و در حالت چندلایه بیشتر دیده می‌شود.")}><input type="checkbox" checked={visualAssets.background3DBlur} onChange={event=>setHeritageVisualAssets({background3DBlur:event.target.checked})}/><span className="theme-checkbox-copy"><strong>{L("Atmospheric layer blur","مه‌ماتی لایه‌ها")}</strong><small>{visualAssets.background3DBlur?L("Enabled · distant layers soften slightly","فعال · لایه‌های دور کمی نرم می‌شوند"):L("Off · keep every layer crisp","خاموش · همه لایه‌ها واضح می‌مانند")}</small></span></label><small className="theme-background-engine-note">{L("These new built-in wallpapers include the provided sample assets, so Heritage can render them as classic flat art, as a multi-layer parallax scene, or through a depth-map driven mesh. Future 3D wallpapers can be added by registering another scene pack in the same background catalog.","این پس‌زمینه‌های داخلی جدید شامل دارایی‌های نمونهٔ ارائه‌شده هستند؛ بنابراین Heritage می‌تواند آن‌ها را به‌صورت تصویر تخت، صحنه پارالاکس چندلایه یا مش مبتنی بر نقشه عمق رندر کند. در آینده نیز می‌توان با ثبت یک scene pack دیگر در همین فهرست، پس‌زمینه‌های سه‌بعدی بیشتری اضافه کرد.")}</small></>}
        <label className="theme-background-fade-toggle theme-checkbox-row" title={L("Adds a soft fade from the scene into the page foundation near the bottom. Leave this off when you want the background artwork to remain continuously visible.","در بخش پایینی صحنه یک محوشدگی نرم به رنگ پایه صفحه اضافه می‌کند. اگر می‌خواهید تصویر پس‌زمینه تا پایین بدون محوشدگی دیده شود، این گزینه را خاموش بگذارید.")}><input type="checkbox" checked={visualAssets.backgroundBottomFade} onChange={event=>setHeritageVisualAssets({backgroundBottomFade:event.target.checked})}/><span className="theme-checkbox-copy"><strong>{L("Bottom background fade","محوشدگی پایین پس‌زمینه")}</strong><small>{visualAssets.backgroundBottomFade?L("Enabled · scene fades into the page foundation","فعال · تصویر در پایین به رنگ پایه صفحه محو می‌شود"):L("Off · no lower-edge wash or fade","خاموش · هیچ پوشش یا محوشدگی در پایین اعمال نمی‌شود")}</small></span></label>
        <div className="theme-asset-actions"><button type="button" onClick={()=>backgroundFileRef.current?.click()}>{visualAssets.customBackground?L("Replace custom background","جایگزینی پس‌زمینه سفارشی"):L("Upload custom background","بارگذاری پس‌زمینه سفارشی")}</button>{visualAssets.customBackground&&<button type="button" onClick={()=>{setHeritageVisualAssets({customBackground:"",backgroundArt:visualAssets.backgroundArt==="custom"?"none":visualAssets.backgroundArt});refreshPaletteAfterSceneChange();}}>{L("Remove custom","حذف سفارشی")}</button>}<input ref={backgroundFileRef} className="theme-json-file" type="file" accept="image/*" onChange={event=>void uploadAsset("background",event)}/></div>
        </div>
      </details>
      <details className="theme-artwork-group theme-artwork-subsection"><summary className="theme-subgroup-head theme-subgroup-toggle"><span className="theme-subgroup-glyph">◇</span><div><strong>{L("Header logo","لوگوی سربرگ")}</strong><small>{L("Choose the compact mark used in the persistent top bar.","نشان فشرده مورد استفاده در نوار بالایی دائمی را انتخاب کنید.")}</small></div><span className="theme-subgroup-chevron" aria-hidden="true">⌄</span></summary><div className="theme-subgroup-body">
        <div className="theme-asset-gallery art-gallery">{HERITAGE_BRAND_ART_OPTIONS.map(option=>{const source=option.id==="custom"?visualAssets.customBrand:option.source;const available=option.id!=="custom"||Boolean(visualAssets.customBrand);const favorite=isHeritageVisualAssetFavorite("brand",option.id,visualAssets);return <div key={option.id} className={`theme-asset-card ${visualAssets.brandArt===option.id?"active":""}`} data-available={available?"true":"false"} data-favorite={favorite?"true":"false"}><button type="button" className={`theme-asset-option ${visualAssets.brandArt===option.id?"active":""}`} data-available={available?"true":"false"} aria-pressed={visualAssets.brandArt===option.id} onClick={()=>{if(option.id==="custom"&&!available)brandFileRef.current?.click();else setHeritageVisualAssets({brandArt:option.id})}}><span className="theme-art-preview">{source?<img src={source} alt=""/>:<i>+</i>}</span><b>{brandLabel(option.id)}</b></button><button type="button" className={`theme-asset-favorite ${favorite?"active":""}`} aria-pressed={favorite} title={favoriteTitle(favorite)} aria-label={`${favoriteTitle(favorite)} · ${brandLabel(option.id)}`} onClick={()=>toggleHeritageVisualAssetFavorite("brand",option.id)}><FavoriteIcon filled={favorite}/></button></div>})}</div>
        <div className="theme-asset-controls">{assetRange(L("Logo scale","مقیاس لوگو"),visualAssets.brandScale,60,145,value=>setHeritageVisualAssets({brandScale:value}))}</div>
        <div className="theme-asset-actions"><button type="button" onClick={()=>brandFileRef.current?.click()}>{visualAssets.customBrand?L("Replace custom logo","جایگزینی لوگوی سفارشی"):L("Upload custom logo","بارگذاری لوگوی سفارشی")}</button>{visualAssets.customBrand&&<button type="button" onClick={()=>setHeritageVisualAssets({customBrand:"",brandArt:visualAssets.brandArt==="custom"?"brand":visualAssets.brandArt})}>{L("Remove custom","حذف سفارشی")}</button>}<input ref={brandFileRef} className="theme-json-file" type="file" accept="image/*" onChange={event=>void uploadAsset("brand",event)}/></div>
        </div>
      </details>
      <details className="theme-artwork-group theme-artwork-subsection"><summary className="theme-subgroup-head theme-subgroup-toggle"><span className="theme-subgroup-glyph">✦</span><div><strong>{L("Welcome / splash art","نشان خوش‌آمدگویی / اسپلش")}</strong><small>{L("Adds more choices on top of the original two hero artworks; the homepage arrows cycle through these same selections.","گزینه‌های بیشتری علاوه بر دو تصویر اصلی اضافه می‌کند؛ فلش‌های صفحه اصلی نیز بین همین گزینه‌ها جابه‌جا می‌شوند.")}</small></div><span className="theme-subgroup-chevron" aria-hidden="true">⌄</span></summary><div className="theme-subgroup-body">
        <div className="theme-asset-gallery art-gallery splash-gallery">{HERITAGE_SPLASH_ART_OPTIONS.map(option=>{const source=option.id==="custom"?visualAssets.customSplash:option.source;const available=option.id!=="custom"||Boolean(visualAssets.customSplash);const favorite=isHeritageVisualAssetFavorite("splash",option.id,visualAssets);const kinetic=option.renderMode==="particle-horse";return <div key={option.id} className={`theme-asset-card ${visualAssets.splashArt===option.id?"active":""}`} data-available={available?"true":"false"} data-favorite={favorite?"true":"false"}><button type="button" className={`theme-asset-option ${visualAssets.splashArt===option.id?"active":""}`} data-available={available?"true":"false"} aria-pressed={visualAssets.splashArt===option.id} onClick={()=>{if(option.id==="custom"&&!available)splashFileRef.current?.click();else setHeritageVisualAssets({splashArt:option.id})}}><span className="theme-art-preview">{kinetic?<span className="particle-horse-mini particle-horse-mini-studio" aria-hidden="true"/>:source?<img src={source} alt=""/>:<i>+</i>}</span><b>{splashLabel(option.id)}</b></button><button type="button" className={`theme-asset-favorite ${favorite?"active":""}`} aria-pressed={favorite} title={favoriteTitle(favorite)} aria-label={`${favoriteTitle(favorite)} · ${splashLabel(option.id)}`} onClick={()=>toggleHeritageVisualAssetFavorite("splash",option.id)}><FavoriteIcon filled={favorite}/></button></div>})}</div>
        <div className="theme-asset-controls">{assetRange(L("Splash scale","مقیاس اسپلش"),visualAssets.splashScale,55,145,value=>setHeritageVisualAssets({splashScale:value}))}</div>
        <div className="theme-asset-actions"><button type="button" onClick={()=>splashFileRef.current?.click()}>{visualAssets.customSplash?L("Replace custom splash","جایگزینی اسپلش سفارشی"):L("Upload custom splash","بارگذاری اسپلش سفارشی")}</button>{visualAssets.customSplash&&<button type="button" onClick={()=>setHeritageVisualAssets({customSplash:"",splashArt:visualAssets.splashArt==="custom"?"heritage":visualAssets.splashArt})}>{L("Remove custom","حذف سفارشی")}</button>}<input ref={splashFileRef} className="theme-json-file" type="file" accept="image/*" onChange={event=>void uploadAsset("splash",event)}/></div>
        </div>
      </details>
      <div className="theme-asset-footer"><small className={assetStatus==="error"?"error":""}>{assetStatus==="working"?L("Optimizing image locally…","در حال بهینه‌سازی محلی تصویر…"):assetStatus==="saved"?L("Custom artwork saved locally ✓","تصویر سفارشی به‌صورت محلی ذخیره شد ✓"):assetStatus==="error"?L("That image could not be saved. Try a smaller PNG, JPG, WebP or AVIF.","ذخیره تصویر ممکن نشد؛ PNG، JPG، WebP یا AVIF کوچک‌تری را امتحان کنید."):L("Custom images stay on this browser/device. Built-in selections, focus controls, fade preference and favorites are included in portable theme JSON.","تصاویر سفارشی فقط در همین مرورگر/دستگاه می‌مانند. انتخاب‌های داخلی، تنظیمات تمرکز، محوشدگی پایین و علاقه‌مندی‌ها داخل JSON قابل‌حمل پوسته ذخیره می‌شوند.")}</small><button type="button" onClick={()=>{resetHeritageVisualAssets();refreshPaletteAfterSceneChange();}}>{L("Reset artwork","بازنشانی تصاویر")}</button></div>
    </section>

    <section id="appearance-material" data-studio-section="material" data-expanded={activeStudioSection==="appearance-material"?"true":"false"} className="theme-settings-block theme-studio-section theme-material-section" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-material"} onClick={()=>activeStudioSection==="appearance-material"?toggleStudioSection("appearance-material"):openStudioSection("appearance-material")}> <span className="theme-section-index">03</span><div><strong>{L("Material & frost","متریال و ماتی")}</strong><small>{L("One semantic glass hierarchy: Outer → Panels → Cards → Controls. Every frosted layer samples and blurs what is behind it.","یک سلسله‌مراتب معنایی شیشه: پوسته بیرونی ← پنل‌ها ← کارت‌ها ← کنترل‌ها. هر لایه مات، آنچه پشت خود است را واقعاً نمونه‌برداری و محو می‌کند.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      {row(L("Glass rendering","نوع شیشه"),L("Frosted keeps real recursive backdrop blur on every material layer. Solid removes only blur; lighting remains a separate system.","حالت مات، محوشدگی واقعی و بازگشتی را در همه لایه‌های متریال حفظ می‌کند. حالت جامد فقط ماتی را حذف می‌کند و نورپردازی مستقل می‌ماند."),<div className="theme-settings-choice two"><button aria-pressed={glassMode} className={glassMode?"active":""} onClick={()=>setGlassMode(true)}><GlassIcon size={14}/>{L("Frosted glass","شیشه مات")}</button><button aria-pressed={!glassMode} className={!glassMode?"active":""} onClick={()=>setGlassMode(false)}>{L("Solid material","متریال جامد")}</button></div>)}
      <div className="theme-material-overview">
        <div className="theme-material-depth-rail" aria-label={L("Material depth order","ترتیب عمق متریال")}>
          <span data-depth="major"><i>1</i><b>{L("Outer","بیرونی")}</b></span><em>›</em>
          <span data-depth="panel"><i>2</i><b>{L("Panels","پنل‌ها")}</b></span><em>›</em>
          <span data-depth="card"><i>3</i><b>{L("Cards","کارت‌ها")}</b></span><em>›</em>
          <span data-depth="control"><i>4</i><b>{L("Controls","کنترل‌ها")}</b></span>
        </div>
        <small>{L("Depth is semantic, not raw DOM nesting. A component keeps the same material role wherever it is reused.","عمق معنایی است، نه تعداد خام تو‌در‌تویی DOM؛ هر مؤلفه هرجا استفاده شود نقش متریال خود را حفظ می‌کند.")}</small><small className="theme-material-performance-note">{L("Performance is automatic: every Frosted layer keeps real blur, while dense screens slightly reduce effective radius and decorative card animation to protect frame rate.","کارایی به‌صورت خودکار مدیریت می‌شود: همه لایه‌های مات، محوشدگی واقعی را حفظ می‌کنند؛ در صفحه‌های بسیار متراکم شعاع مؤثر و انیمیشن تزئینی کارت‌ها کمی کاهش می‌یابد تا نرخ فریم حفظ شود.")}</small>
      </div>
      <div className="theme-material-master"><div><strong>{L("Shared surface polish","پرداخت مشترک سطوح")}</strong><small>{L("A restrained halo around major glass surfaces. It does not change backdrop blur.","هاله‌ای کنترل‌شده پیرامون سطوح اصلی شیشه؛ قدرت ماتی پس‌زمینه را تغییر نمی‌دهد.")}</small></div>{slider("haloSoftness",L("Outer halo softness","نرمی هاله بیرونی"),12,52,1,"px",L("Softness of restrained outer glass halos and focus depth. It does not alter recursive blur strength.","نرمی هاله‌های محدود بیرونی و عمق فوکوس را کنترل می‌کند و قدرت ماتی بازگشتی را تغییر نمی‌دهد."))}</div>
      <div className="theme-material-depth-stack">
        <article className="theme-material-depth-card" data-depth="major">
          <div className="theme-depth-card-head"><span className="theme-depth-index">01</span><div><strong>{L("Outer shell","پوسته بیرونی")}</strong><small>{L("Largest workspaces, detached windows and page-level glass surfaces.","بزرگ‌ترین فضاهای کاری، پنجره‌های جدا و سطوح شیشه‌ای سطح صفحه.")}</small></div><span className="theme-depth-role">{L("BASE","پایه")}</span></div>
          <div className="theme-depth-controls">{slider("majorTransparency",L("Transparency","شفافیت"),35,92,1,"%",L("How much scenery remains visible through Outer material.","میزان دیده‌شدن صحنه از متریال پوسته بیرونی."))}{slider("majorBrightness",L("Material shade","سایه متریال"),-100,100,1,"",L("Negative values mix the actual translucent Outer material toward black; -100 is pure black at the selected transparency. Positive values lift it toward white. Text, Ambient and semantic color stay untouched.","مقادیر منفی خود متریال شفاف بیرونی را به سمت مشکی می‌برند؛ ۱۰۰- در شفافیت انتخاب‌شده مشکی خالص است. مقادیر مثبت آن را به سمت سفید می‌برند. متن، نور محیطی و رنگ معنایی دست‌نخورده می‌مانند."),[L("Black","مشکی"),L("Neutral","خنثی"),L("White","سفید")])}{slider("majorSaturation",L("Material saturation","اشباع متریال"),0,200,1,"%",L("Color intensity of Outer material. 100% preserves the designed palette.","شدت رنگ متریال بیرونی؛ ۱۰۰٪ پالت طراحی‌شده را حفظ می‌کند."))}{slider("majorBlur",L("Backdrop blur","ماتی پس‌زمینه"),4,64,1,"px",L("Real recursive blur sampled by Outer surfaces.","ماتی واقعی و بازگشتی که سطوح بیرونی از پشت خود نمونه‌برداری می‌کنند."))}</div>
        </article>
        <article className="theme-material-depth-card" data-depth="panel">
          <div className="theme-depth-card-head"><span className="theme-depth-index">02</span><div><strong>{L("Inner panels","پنل‌های داخلی")}</strong><small>{L("Sections and work areas contained inside an Outer surface.","بخش‌ها و نواحی کاری قرارگرفته داخل یک سطح بیرونی.")}</small></div><span className="theme-depth-role">{L("SECTION","بخش")}</span></div>
          <div className="theme-depth-controls">{slider("panelTransparency",L("Transparency","شفافیت"),35,90,1,"%",L("Transparency of Panel material.","شفافیت متریال پنل."))}{slider("panelBrightness",L("Material shade","سایه متریال"),-100,100,1,"",L("Push Panel material toward transparent black or transparent white without altering its content or lighting.","متریال پنل را بدون تغییر محتوا یا نورپردازی به سمت مشکی شفاف یا سفید شفاف ببرید."),[L("Black","مشکی"),L("Neutral","خنثی"),L("White","سفید")])}{slider("panelSaturation",L("Material saturation","اشباع متریال"),0,200,1,"%",L("Color intensity of Panel material only.","شدت رنگ فقط برای متریال پنل."))}{slider("panelBlur",L("Backdrop blur","ماتی پس‌زمینه"),4,64,1,"px",L("Real recursive Panel blur. The calibrated default is lighter than Outer for clarity and performance.","ماتی واقعی و بازگشتی پنل؛ مقدار پیش‌فرض برای وضوح و کارایی از لایه بیرونی سبک‌تر است."))}</div>
        </article>
        <article className="theme-material-depth-card" data-depth="card">
          <div className="theme-depth-card-head"><span className="theme-depth-index">03</span><div><strong>{L("Content cards","کارت‌های محتوا")}</strong><small>{L("Repeated information, metrics, horse nodes and analytical cards.","کارت‌های تکرارشونده اطلاعات، شاخص‌ها، گره‌های اسب و تحلیل‌ها.")}</small></div><span className="theme-depth-role">{L("CONTENT","محتوا")}</span></div>
          <div className="theme-depth-controls">{slider("cardTransparency",L("Transparency","شفافیت"),25,86,1,"%",L("Transparency of Card material.","شفافیت متریال کارت."))}{slider("cardBrightness",L("Material shade","سایه متریال"),-100,100,1,"",L("Card material can reach pure transparent black at -100, useful for deep nested cards in Dark mode.","متریال کارت در ۱۰۰- می‌تواند به مشکی شفاف خالص برسد؛ برای کارت‌های عمیق در حالت تیره مناسب است."),[L("Black","مشکی"),L("Neutral","خنثی"),L("White","سفید")])}{slider("cardSaturation",L("Material saturation","اشباع متریال"),0,200,1,"%",L("Color intensity of Card material only.","شدت رنگ فقط برای متریال کارت."))}{slider("cardBlur",L("Backdrop blur","ماتی پس‌زمینه"),3,48,1,"px",L("Real recursive Card blur, calibrated lower than large surfaces for responsive dense layouts.","ماتی واقعی و بازگشتی کارت، برای چیدمان‌های متراکم و روان کمتر از سطوح بزرگ تنظیم شده است."))}</div>
        </article>
        <article className="theme-material-depth-card" data-depth="control">
          <div className="theme-depth-card-head"><span className="theme-depth-index">04</span><div><strong>{L("Interactive controls","کنترل‌های تعاملی")}</strong><small>{L("Tabs, toolbars, segmented controls and compact interactive chrome.","تب‌ها، نوارابزارها، کنترل‌های قطعه‌ای و اجزای تعاملی فشرده.")}</small></div><span className="theme-depth-role">{L("ACTION","تعامل")}</span></div>
          <div className="theme-depth-controls">{slider("controlTransparency",L("Transparency","شفافیت"),20,80,1,"%",L("Transparency of compact Control material.","شفافیت متریال کنترل‌های فشرده."))}{slider("controlBrightness",L("Material shade","سایه متریال"),-100,100,1,"",L("Control material can be independently pushed toward black or white while labels and icons remain unchanged.","متریال کنترل را می‌توان مستقل به سمت مشکی یا سفید برد، در حالی که برچسب‌ها و آیکن‌ها تغییر نمی‌کنند."),[L("Black","مشکی"),L("Neutral","خنثی"),L("White","سفید")])}{slider("controlSaturation",L("Material saturation","اشباع متریال"),0,200,1,"%",L("Color intensity of Control material only.","شدت رنگ فقط برای متریال کنترل."))}{slider("controlBlur",L("Backdrop blur","ماتی پس‌زمینه"),2,32,1,"px",L("Real recursive blur for compact controls. Smaller radii preserve responsiveness in dense navigation.","ماتی واقعی و بازگشتی کنترل‌های فشرده؛ شعاع کمتر، روانی ناوبری متراکم را حفظ می‌کند."))}</div>
        </article>
      </div>
    </section>

    <section id="appearance-lighting" data-studio-section="lighting" data-expanded={activeStudioSection==="appearance-lighting"?"true":"false"} className="theme-settings-block theme-studio-section theme-settings-atmosphere" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-lighting"} onClick={()=>activeStudioSection==="appearance-lighting"?toggleStudioSection("appearance-lighting"):openStudioSection("appearance-lighting")}> <span className="theme-section-index">04</span><div><strong>{L("Ambient & shine","نور محیطی و درخشش")}</strong><small>{L("Post-material effects only. These controls never own glass fill, transparency or backdrop blur.","فقط افکت‌های پس از متریال؛ این کنترل‌ها هرگز مالک پس‌زمینه شیشه، شفافیت یا ماتی نیستند.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      {row(L("Ambient state","حالت نور محیطی"),L("Animated moves the light field; Still keeps the same field frozen; Off removes only Ambient lighting.","متحرک میدان نور را حرکت می‌دهد؛ ثابت همان میدان را بدون حرکت نگه می‌دارد؛ خاموش فقط نور محیطی را حذف می‌کند."),<div className="theme-settings-choice three"><button aria-pressed={ambientMotion==="animated"} className={ambientMotion==="animated"?"active":""} onClick={()=>setAmbientMotion("animated")}><span aria-hidden="true">≈</span>{L("Animated","متحرک")}</button><button aria-pressed={ambientMotion==="still"} className={ambientMotion==="still"?"active":""} onClick={()=>setAmbientMotion("still")}><span aria-hidden="true">—</span>{L("Still","ثابت")}</button><button aria-pressed={ambientMotion==="off"} className={ambientMotion==="off"?"active":""} onClick={()=>setAmbientMotion("off")}><span aria-hidden="true">○</span>{L("Off","خاموش")}</button></div>)}
      {row(L("Ambient style","سبک نور محیطی"),L("Organic Drift is restrained and tonal. Chromatic Depth uses three complementary scheme-derived colors. Constant Orbit slowly rotates the whole field; Steady Drift glides it diagonally; Breathe pulses it softly.","حرکت ارگانیک تونال و کنترل‌شده است؛ عمق رنگی از سه رنگ مکمل مشتق‌شده از طرح استفاده می‌کند. چرخش دائم کل میدان را آرام می‌چرخاند؛ جابه‌جایی پیوسته آن را مورب می‌برد؛ تنفس آن را نرم می‌تپد."),<div className="theme-settings-choice ambient-pattern-choice">{HERITAGE_AMBIENT_PATTERNS.map(value=><button key={value} aria-pressed={ambientPattern===value} className={ambientPattern===value?"active":""} onClick={()=>setAmbientPattern(value)}><span aria-hidden="true">{value==="organic"?"≈":value==="chromatic"?"◌":value==="orbit"?"↻":value==="drift"?"⇢":"◍"}</span>{ambientPatternLabel(value)}</button>)}</div>)}
      {row(L("Ambient layers","لایه‌های نور محیطی"),L("The colorful animated field is painted on the selected material layers only. Layer 01 Outer shell is the calm default; deeper layers can be opted back in.","میدان رنگی متحرک فقط روی لایه‌های انتخاب‌شده نقاشی می‌شود. لایه ۰۱ (پوسته بیرونی) حالت آرام پیش‌فرض است؛ لایه‌های عمیق‌تر اختیاری هستند."),<div className="theme-settings-choice">{HERITAGE_AMBIENT_LAYER_SELECTIONS.map(value=><button key={value} aria-pressed={ambientLayers===value} className={ambientLayers===value?"active":""} onClick={()=>setAmbientLayers(value)}>{value==="major"?L("01 Outer only","فقط ۰۱ بیرونی"):value==="major,panel"?L("01 + 02 panels","۰۱ + ۰۲"):L("01–03 with cards","۰۱ تا ۰۳")}</button>)}</div>)}
      {row(L("Apply ambient to","اعمال نور محیطی روی"),L("Surfaces lights each material surface locally; Outer limits it to the largest surfaces; Global uses one full-page atmosphere.","سطوح، هر متریال را جداگانه نورپردازی می‌کند؛ بیرونی فقط بزرگ‌ترین سطوح را روشن می‌کند؛ سراسری یک اتمسفر تمام‌صفحه می‌سازد."),<div className="theme-settings-choice three">{HERITAGE_AMBIENT_SCOPES.map(value=><button key={value} aria-pressed={ambientScope===value} className={ambientScope===value?"active":""} onClick={()=>setAmbientScope(value)}>{value==="surfaces"?L("All surfaces","همه سطوح"):value==="major"?L("Outer only","فقط بیرونی"):L("Global","سراسری")}</button>)}</div>)}
      <label className="theme-checkbox-row theme-effect-toggle" title={L("Adds subtle ordered noise inside the moving light field itself. It moves and freezes with Ambient rather than becoming a static page texture.","نویز مرتب و ظریفی را داخل خود میدان نور اضافه می‌کند؛ همراه نور حرکت و متوقف می‌شود و به بافت ثابت صفحه تبدیل نمی‌شود.")}><input type="checkbox" checked={ambientDither} onChange={e=>setAmbientDither(e.target.checked)}/><span className="theme-checkbox-copy"><strong>{L("Moving ambient dithering","دیترینگ متحرک نور")}</strong><small>{L("Optional banding reduction attached only to Ambient gradients.","کاهش اختیاری نواربندی که فقط به گرادیان‌های نور محیطی متصل است.")}</small></span></label>
      <div className="theme-settings-subgroup theme-effect-card" data-effect="ambient"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">≈</span><div><strong>{L("Ambient field","میدان نور محیطی")}</strong><small>{L("Color energy and movement of the atmospheric light itself.","انرژی رنگ و حرکت خود نور اتمسفری.")}</small></div></div><div className="theme-tuning-grid atmosphere-controls">
        {slider("ambientVisibility",L("Strength","قدرت"),0,200,1,"%",L("Master energy of Ambient lighting. 100% is the calibrated reference.","انرژی اصلی نور محیطی؛ ۱۰۰٪ مرجع تنظیم‌شده است."))}
        {slider("ambientBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-50,50,1,"%",L("Grades Ambient source colors only. Negative is darker; positive is brighter.","فقط رنگ‌های منبع نور محیطی را تنظیم می‌کند؛ منفی تیره‌تر و مثبت روشن‌تر است."))}
        {slider("ambientSaturation",L("Saturation / chroma","اشباع / خلوص رنگ"),0,220,1,"%",L("True Ambient chroma. Raising this intensifies color without intentionally increasing brightness; use Brightness / darkness separately for a dark saturated look.","خلوص واقعی رنگ نور محیطی؛ افزایش آن رنگ را قوی‌تر می‌کند بدون اینکه عمداً روشنایی را بالا ببرد. برای ظاهر تیره و اشباع، روشنایی / تیرگی را جداگانه تنظیم کنید."))}
        {slider("motionSeconds",L("Movement cycle","چرخه حرکت"),8,36,1,"s",L("Duration of one Ambient cycle. Lower is faster; higher is calmer.","مدت یک چرخه نور محیطی؛ کمتر سریع‌تر و بیشتر آرام‌تر است."))}
      </div></div>
      <div className="theme-settings-subgroup theme-effect-card" data-effect="shine"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">／</span><div><strong>{L("Glass highlight","درخشش شیشه")}</strong><small>{L("A local soft specular sweep on Outer and Panel surfaces only—never a global page sweep.","درخشش نرم و محلی فقط روی سطوح بیرونی و پنل‌ها؛ هرگز جاروب سراسری صفحه نیست.")}</small></div></div><div className="theme-tuning-grid atmosphere-controls">
        {slider("shineEnergy",L("Strength","قدرت"),0,40,1,"%",L("Energy of the moving glass highlight.","انرژی درخشش متحرک شیشه."))}
        {slider("shineBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-50,50,1,"%",L("Grades only the highlight source color.","فقط رنگ منبع درخشش را روشن یا تیره می‌کند."))}
        {slider("shineSaturation",L("Saturation","اشباع"),0,220,1,"%",L("Color intensity of the highlight source.","شدت رنگ منبع درخشش."))}
        {slider("shineSeconds",L("Movement cycle","چرخه حرکت"),10,42,1,"s",L("Duration of one side-to-side highlight cycle.","مدت یک چرخه رفت‌وبرگشت درخشش."))}
      </div>{checkbox("shineMotion",L("Animate glass highlight","درخشش شیشه متحرک"),L("Enables the local highlight animation on eligible Outer and Panel surfaces.","حرکت درخشش محلی را روی سطوح بیرونی و پنل‌های واجد شرایط فعال می‌کند."))}</div>
    </section>

    <section id="appearance-color" data-studio-section="color" data-expanded={activeStudioSection==="appearance-color"?"true":"false"} className="theme-settings-block theme-studio-section" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-color"} onClick={()=>activeStudioSection==="appearance-color"?toggleStudioSection("appearance-color"):openStudioSection("appearance-color")}> <span className="theme-section-index">05</span><div><strong>{L("Color & meaning","رنگ و معنا")}</strong><small>{L("Tune decorative color separately from meaning-bearing sire, dam, warning, success and status colors.","رنگ تزئینی را جدا از رنگ‌های دارای معنا مانند پدر، مادر، هشدار، موفقیت و وضعیت تنظیم کنید.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      <div className="theme-settings-subgroup theme-color-group" data-color-group="scheme"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">◇</span><div><strong>{L("Decorative scheme","طرح تزئینی")}</strong><small>{L("Global palette character. It never changes the meaning of semantic colors.","شخصیت پالت کلی؛ معنای رنگ‌های معنایی را تغییر نمی‌دهد.")}</small></div></div><div className="theme-tuning-grid scheme-expression-controls">
        {slider("schemeEnergy",L("Scheme character","شخصیت طرح"),0,22,1,"%",L("Presence of the selected palette across the glass foundation, chrome and global accents.","میزان حضور پالت انتخابی در پایه شیشه، کروم و لهجه‌های کلی."))}
        {slider("schemeBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-30,30,1,"%",L("Raises or lowers the decorative scheme only.","فقط طرح تزئینی را روشن یا تیره می‌کند."))}
        {slider("schemeSaturation",L("Saturation","اشباع"),0,200,1,"%",L("Color intensity of the decorative scheme.","شدت رنگ طرح تزئینی."))}
        {slider("schemeContrast",L("Contrast","کنتراست"),-40,40,1,"%",L("Separation between decorative accents and the glass foundation.","جدایی میان لهجه‌های تزئینی و پایه شیشه."))}
      </div></div>
      <div className="theme-settings-subgroup semantic-lab theme-color-group" data-color-group="semantic"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">●</span><div><strong>{L("Semantic colors","رنگ‌های معنایی")}</strong><small>{L("Used for sire/dam, warnings, success, statuses and other information where color carries meaning.","برای پدر/مادر، هشدار، موفقیت، وضعیت و اطلاعاتی که رنگ در آن معنا دارد استفاده می‌شود.")}</small></div></div>
        <div className="theme-color-lab-part"><span>{L("Background fill","پس‌زمینه")}</span><div className="theme-tuning-grid color-channel-controls">
          {slider("semanticBackgroundVisibility",L("Fill strength","قدرت رنگ"),0,100,1,"%",L("Visibility of semantic background color only.","فقط وضوح رنگ پس‌زمینه معنایی."))}
          {slider("semanticBackgroundBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-30,30,1,"%",L("Brightness of semantic background fills only.","روشنایی فقط برای پس‌زمینه‌های معنایی."))}
          {slider("semanticBackgroundSaturation",L("Saturation","اشباع"),0,200,1,"%",L("Color intensity of semantic background fills only.","شدت رنگ فقط برای پس‌زمینه‌های معنایی."))}
        </div></div>
        <div className="theme-color-lab-part"><span>{L("Text & accents","متن و نشانه‌ها")}</span><div className="theme-tuning-grid color-channel-controls">
          {slider("semanticTextVisibility",L("Text color strength","قدرت رنگ متن"),0,100,1,"%",L("How strongly semantic text uses its meaning color.","شدت استفاده متن معنایی از رنگ دارای معنا."))}
          {slider("tintEnergy",L("Border & cue strength","قدرت مرز و نشانه"),0,40,1,"%",L("Strength of semantic borders, rails and compact cues.","قدرت مرزها، ریل‌ها و نشانه‌های فشرده معنایی."))}
          {slider("semanticBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-30,30,1,"%",L("Brightness of semantic foreground colors only.","روشنایی فقط برای رنگ‌های معنایی پیش‌زمینه."))}
          {slider("semanticSaturation",L("Saturation","اشباع"),0,200,1,"%",L("Color intensity of semantic foreground colors only.","شدت رنگ فقط برای رنگ‌های معنایی پیش‌زمینه."))}
        </div></div>
      </div>
      <div className="theme-settings-subgroup theme-color-group" data-color-group="context"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">▦</span><div><strong>{L("Contextual colors","رنگ‌های زمینه‌ای")}</strong><small>{L("Decorative grouping for metrics, results and analytical blocks; these colors do not carry status meaning.","گروه‌بندی تزئینی برای شاخص‌ها، نتایج و بلوک‌های تحلیلی؛ این رنگ‌ها معنای وضعیت ندارند.")}</small></div></div><div className="theme-tuning-grid color-channel-controls">
        {slider("contextColorEnergy",L("Accent strength","قدرت لهجه"),0,28,1,"%",L("Strength of non-semantic contextual accents.","قدرت لهجه‌های زمینه‌ای غیرمعنایی."))}
        {slider("contextBackgroundVisibility",L("Background visibility","وضوح پس‌زمینه"),0,100,1,"%",L("Visibility of contextual colored fills.","وضوح رنگ پس‌زمینه بلوک‌های زمینه‌ای."))}
        {slider("contextColorBrightness",L("Brightness / darkness","روشنایی / تیرگی"),-30,30,1,"%",L("Brightness of contextual grouping colors.","روشنایی رنگ‌های گروه‌بندی زمینه‌ای."))}
        {slider("contextColorSaturation",L("Saturation","اشباع"),0,200,1,"%",L("Color intensity of contextual grouping colors.","شدت رنگ‌های گروه‌بندی زمینه‌ای."))}
      </div></div>
    </section>

    <section id="appearance-navigation" data-studio-section="navigation" data-expanded={activeStudioSection==="appearance-navigation"?"true":"false"} className="theme-settings-block theme-studio-section" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-navigation"} onClick={()=>activeStudioSection==="appearance-navigation"?toggleStudioSection("appearance-navigation"):openStudioSection("appearance-navigation")}> <span className="theme-section-index">06</span><div><strong>{L("Navigation & layout","ناوبری و چیدمان")}</strong><small>{L("Choose how workspace tabs are arranged, how dense the layout is, and how strongly interactive controls stand out from passive glass.","چیدمان تب‌ها، تراکم چیدمان و میزان برجستگی کنترل‌های تعاملی نسبت به شیشه غیرفعال را تعیین کنید.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      {row(L("Navigation layout", "چیدمان منو"), L("Automatic uses a sidebar only when there is room for both the navigation and a full registry workspace. Your manual choice is preserved.", "حالت خودکار فقط وقتی فضای کافی برای منو و فهرست کامل وجود دارد، منوی کناری را نمایش می‌دهد. انتخاب دستی شما حفظ می‌شود."), <LayoutSwitcher locale={locale}/>)}
      {row(L("Tab hierarchy","سلسله‌مراتب تب‌ها"),L("Contextual groups tabs by workspace; Stacked shows explicit rows; Docked uses the compact dock treatment.","زمینه‌ای تب‌ها را بر اساس فضای کاری گروه‌بندی می‌کند؛ ردیفی ردیف‌های صریح نشان می‌دهد؛ داک از چیدمان فشرده داک استفاده می‌کند."),<div className="theme-settings-choice three"><button aria-pressed={tabHierarchy==="contextual"} className={tabHierarchy==="contextual"?"active":""} onClick={()=>setTabHierarchy("contextual")}>{L("Contextual","زمینه‌ای")}</button><button aria-pressed={tabHierarchy==="stacked"} className={tabHierarchy==="stacked"?"active":""} onClick={()=>setTabHierarchy("stacked")}>{L("Stacked","ردیفی")}</button><button aria-pressed={tabHierarchy==="docked"} className={tabHierarchy==="docked"?"active":""} onClick={()=>setTabHierarchy("docked")}>{L("Docked · EXP","داک · آزمایشی")}</button></div>)}
      {row(L("Layout density","تراکم چیدمان"),L("Compact reduces paddings, gaps and section chrome so smaller screens fit meaningfully more content. Phones default to Compact.","حالت فشرده فاصله‌ها و حاشیه‌ها را کم می‌کند تا صفحه‌های کوچک محتوای بیشتری جا دهند. موبایل به‌طور پیش‌فرض فشرده است."),<div className="theme-settings-choice">{HERITAGE_DENSITY_MODES.map(value=><button key={value} aria-pressed={density===value} className={density===value?"active":""} onClick={()=>setDensity(value)}>{value==="comfortable"?L("Comfortable","راحت"):L("Compact","فشرده")}</button>)}</div>)}
      {row(L("Performance mode","حالت کارایی"),L("Auto detects weak devices and slows decoration only where needed. Full always keeps every effect; Lite stops ambient/shine animations and the heaviest decoration for maximum smoothness.","خودکار دستگاه‌های ضعیف را تشخیص می‌دهد و فقط در صورت نیاز تزیینات را سبک می‌کند. کامل همه جلوه‌ها را نگه می‌دارد؛ سبک انیمیشن‌های نور و درخشش و سنگین‌ترین تزیینات را برای بیشترین روانی متوقف می‌کند."),<div className="theme-settings-choice">{HERITAGE_PERFORMANCE_MODES.map(value=><button key={value} aria-pressed={performanceMode===value} className={performanceMode===value?"active":""} onClick={()=>setPerformanceMode(value)}>{value==="auto"?L("Auto","خودکار"):value==="full"?L("Full","کامل"):L("Lite","سبک")}</button>)}</div>)}
      <div className="theme-settings-subgroup theme-layout-spacing"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">⇕</span><div><strong>{L("Spacing & margins","فاصله‌ها و حاشیه‌ها")}</strong><small>{layoutTuned?L("Customized · these live sliders override density mode while changed. Move anything back to its default to return to the curated rhythm.","سفارشی‌شده · این لغزنده‌ها تا زمانی که مقدار سفارشی داشته باشند بر حالت تراکم اولویت می‌یابند. با بازگرداندن همه به پیش‌فرض، ریتم اصلی بازمی‌گردد."):L("Real-time layout tuning. Every slider updates the page instantly; defaults mirror the curated rhythm so nothing changes until you move a slider.","تنظیم زندهٔ چیدمان. هر لغزنده بلافاصله صفحه را به‌روزرسانی می‌کند؛ پیش‌فرض‌ها همان ریتم اصلی هستند تا وقتی لغزنده‌ای را حرکت ندهید هیچ چیز عوض نشود.")}</small></div></div><div className="theme-tuning-grid atmosphere-controls">
        {layoutSlider("pageTop",L("Top margin · below the header","حاشیه بالا · زیر سربرگ"),L("Vertical breathing room between the fixed top bar and the first content container.","فضای عمودی بین نوار بالایی ثابت و نخستین بخش محتوا."))}
        {layoutSlider("pageBottom",L("Bottom margin","حاشیه پایین"),L("Vertical space after the last container, above the footer zone.","فضای عمودی پس از آخرین بخش، ناحیه قبل از پاصفحه."))}
        {layoutSlider("sideGutter",L("Side gutter","حاشیه کناری"),L("Horizontal padding between the viewport edges and the content column.","فاصله افقی بین لبهٔ صفحه و ستون محتوا."))}
        {layoutSlider("sectionGap",L("Gap between containers","فاصله بین بخش‌ها"),L("Vertical rhythm between the major containers on every page.","ریتم عمودی میان بخش‌های اصلی در همهٔ صفحات."))}
        {layoutSlider("panelInset",L("Padding inside containers","پرداختی داخل بخش‌ها"),L("Inner padding of glass panels and cards.","حاشیه داخلی پنل‌ها و کارت‌های شیشه‌ای."))}
        {layoutSlider("contentWidth",L("Content width","عرض محتوا"),L("Maximum width of the reading column; the home hero stays slightly wider.","بیشینهٔ عرض ستون محتوا؛ بخش قهرمان صفحه اصلی کمی پهن‌تر می‌ماند."))}
        <div className="theme-layout-spacing-footer">
          <small>{L("Defaults:","پیش‌فرض‌ها:")} {L("top","بالا")} {tuningFormatter.format(DEFAULT_HERITAGE_LAYOUT.pageTop)} · {L("bottom","پایین")} {tuningFormatter.format(DEFAULT_HERITAGE_LAYOUT.pageBottom)} · {L("gap","فاصله")} {tuningFormatter.format(DEFAULT_HERITAGE_LAYOUT.sectionGap)} · {L("inset","داخلی")} {tuningFormatter.format(DEFAULT_HERITAGE_LAYOUT.panelInset)} · {L("width","عرض")} {tuningFormatter.format(DEFAULT_HERITAGE_LAYOUT.contentWidth)}</small>
          <button type="button" className="theme-layout-reset-button" onClick={()=>resetHeritageLayout()} disabled={!layoutTuned}>{layoutTuned?L("Reset spacing","بازنشانی فاصله‌ها"):L("Using curated defaults","در حال استفاده از پیش‌فرض‌ها")}</button>
        </div>
      </div></div>
      <div className="theme-settings-subgroup theme-navigation-emphasis"><div className="theme-subgroup-head"><span className="theme-subgroup-glyph">⌁</span><div><strong>{L("Interactive emphasis","تأکید تعاملی")}</strong><small>{L("A separate token layer for interaction states. Material 01–04 still describes structural depth; these controls only tune how selected and interactive states announce themselves.","یک لایه توکن جدا برای حالت‌های تعاملی است. متریال ۰۱ تا ۰۴ همچنان فقط عمق ساختاری را تعریف می‌کند؛ این کنترل‌ها فقط نحوه برجسته‌شدن حالت‌های انتخاب‌شده و تعاملی را تنظیم می‌کنند.")}</small></div></div><div className="theme-tuning-grid atmosphere-controls">
        {slider("controlProminence",L("Control prominence","برجستگی کنترل‌ها"),0,100,1,"%",L("Makes all interactive controls more distinct from passive glass through denser fill and clearer edges.","همه کنترل‌های تعاملی را با پس‌زمینه متراکم‌تر و لبه واضح‌تر از شیشه غیرفعال متمایز می‌کند."))}
        {slider("selectedStateStrength",L("Selected-state strength","قدرت حالت انتخاب‌شده"),0,100,1,"%",L("Controls active-tab fill, border strength and foreground emphasis without changing Material Depth.","قدرت پس‌زمینه، مرز و تأکید تب فعال را بدون تغییر عمق متریال کنترل می‌کند."))}
        {slider("selectedStateSaturation",L("Selected saturation","اشباع حالت انتخاب‌شده"),50,220,1,"%",L("Color intensity of active tabs and selected controls only.","شدت رنگ فقط برای تب‌ها و کنترل‌های انتخاب‌شده."))}
        {slider("selectedStateGlow",L("Selected glow","درخشش حالت انتخاب‌شده"),0,100,1,"%",L("Adds a controlled accent halo around the current selection.","یک هاله کنترل‌شده رنگی پیرامون انتخاب فعلی اضافه می‌کند."))}
        {slider("selectedStateMotion",L("Selected motion","حرکت حالت انتخاب‌شده"),0,100,1,"%",L("Controls the amplitude of the selected-state breathing/lift animation. Reduced-motion preferences always disable it.","دامنه حرکت تنفسی/بالاآمدن حالت انتخاب‌شده را کنترل می‌کند. تنظیم کاهش حرکت سیستم همیشه آن را غیرفعال می‌کند."))}
      </div></div>
    </section>

    <section id="appearance-presets" data-studio-section="preset" data-expanded={activeStudioSection==="appearance-presets"?"true":"false"} className="theme-settings-block theme-studio-section theme-studio-presets" data-h-surface-role="panel">
      <button type="button" className="theme-settings-block-head theme-studio-section-head theme-studio-section-toggle" aria-expanded={activeStudioSection==="appearance-presets"} onClick={()=>activeStudioSection==="appearance-presets"?toggleStudioSection("appearance-presets"):openStudioSection("appearance-presets")}> <span className="theme-section-index">07</span><div><strong>{L("Presets & reset","پیش‌تنظیم و بازنشانی")}</strong><small>{L("Save, restore or share the complete visual configuration. Reset affects fine-tuning values only, not your language or current page.","پیکربندی کامل ظاهر را ذخیره، بازیابی یا به اشتراک بگذارید؛ بازنشانی فقط مقادیر تنظیم دقیق را تغییر می‌دهد و زبان یا صفحه فعلی را دست نمی‌زند.")}</small></div><span className="theme-section-chevron" aria-hidden="true">⌄</span></button>
      <div className="theme-reset-card theme-complete-preset-card"><div><strong>{L("R24 default appearance","ظاهر پیش‌فرض R24")}</strong><small>{L("Apply the complete built-in default: Auto palette, Light mode, calibrated materials, Achaemenid dawn wallpaper and Q8 splash art.","پیش‌فرض کامل داخلی را اعمال کنید: پالت خودکار، حالت روشن، متریال تنظیم‌شده، پس‌زمینه سپیده‌دم هخامنشی و نشان Q8.")}</small></div><button type="button" onClick={()=>applyBuiltInPreset("default")}>{L("Apply R24 default","اعمال پیش‌فرض R24")}</button></div>
      <div className="theme-reset-card theme-complete-preset-card legacy"><div><strong>{L("Legacy R23 defaults","پیش‌فرض‌های قدیمی R23")}</strong><small>{L("Restore the complete pre-R24 built-in appearance in one click, including the adaptive wallpaper and Heritage splash.","ظاهر داخلی پیش از R24 را با یک کلیک بازیابی کنید؛ شامل پس‌زمینه تطبیقی و نشان Heritage.")}</small></div><button type="button" onClick={()=>applyBuiltInPreset("legacy-r23")}>{L("Apply Legacy R23","اعمال R23 قدیمی")}</button></div>
      <div className="theme-reset-card"><div><strong>{L("Recommended fine-tuning defaults","مقادیر پیشنهادی تنظیم دقیق")}</strong><small>{L("Restore the R24 material, lighting and color tuning while keeping the currently selected Foundation and artwork choices.","مقادیر متریال، نور و رنگ R24 را بازگردانید و انتخاب‌های فعلی پایه و آثار تصویری را حفظ کنید.")}</small></div><button type="button" onClick={()=>setThemeTuning(DEFAULT_THEME_TUNING)}>{L("Reset fine tuning","بازنشانی تنظیم دقیق")}</button></div>
      <div className="theme-json-actions">
        <div className="theme-json-actions-head"><strong>{L("Portable theme preset","پیش‌تنظیم قابل حمل")}{help(L("Export saves palette, material depth, Ambient, navigation and fine color controls. Import validates and clamps values before applying them.","خروجی پالت، عمق متریال، نور محیطی، ناوبری و کنترل‌های دقیق رنگ را ذخیره می‌کند؛ ورود فایل مقادیر را پیش از اعمال اعتبارسنجی و محدود می‌کند."))}</strong></div>
        <div className="theme-json-buttons"><button type="button" onClick={downloadThemeJson}>{L("Export JSON","خروجی JSON")}</button><button type="button" onClick={()=>themeFileRef.current?.click()}>{L("Import JSON","ورود JSON")}</button><button type="button" className="theme-json-copy" onClick={copyThemeJson}>{themeCopied?L("Copied ✓","کپی شد ✓"):L("Copy JSON","کپی JSON")}</button></div>
        <input ref={themeFileRef} className="theme-json-file" type="file" accept="application/json,.json" onChange={importThemeJson}/>
        <small className={themePresetStatus==="invalid"?"theme-json-status error":"theme-json-status"}>{themePresetStatus==="imported"?L("Theme imported successfully.","پوسته با موفقیت وارد شد."):themePresetStatus==="invalid"?L("That file is not a valid Horse Registry theme preset.","این فایل یک پیش‌تنظیم معتبر سامانه ثبت اسب نیست."):L("Export this exact appearance for backup, sharing or later restoration.","این ظاهر دقیق را برای پشتیبان‌گیری، اشتراک‌گذاری یا بازیابی بعدی خروجی بگیرید.")}</small>
      </div>
    </section>
  </aside>;
  return <div className="theme-controls" role="group" aria-label={L("Appearance settings","تنظیمات ظاهر")}>
    <div className={`theme-settings-menu${settingsOpen?" open":""}`}>
      <button ref={triggerRef} type="button" className="theme-settings-trigger" onClick={toggleSettings} title={L("Appearance & theme settings","تنظیمات ظاهر و پوسته")} aria-label={L("Appearance & theme settings","تنظیمات ظاهر و پوسته")} aria-expanded={settingsOpen} aria-controls="heritage-appearance-studio"><ThemeSettingsIcon/></button>
    </div>
    {settingsOpen&&typeof document!=="undefined"?createPortal(<div className="theme-settings-portal-layer" aria-hidden="false"><HeritageLightingOverlay portal/>{settingsPanel}</div>,document.body):null}
    <button className="mode-toggle" onClick={()=>setMode(mode==="dark"?"light":"dark")} title={t("theme.mode")} aria-label={t("theme.mode")}>{mode==="dark"?<SunIcon/>:<MoonIcon/>}</button>
  </div>;
}

